std::array<Property,4> arguments(int mode){if(mode==0)return {PropertyList{},false,0,false};if(mode==1)return {Missing{},Missing{},Missing{},Missing{}};if(mode==2)return {PropertyList{},PropertyNull{},"2","x"};return {PropertyList{},true,2,true};}
